export const PROGRAM_NAME = 'test2_executable';
export const USAGE_LINE = `usage: ${PROGRAM_NAME} [-h] --a A --b B`;
export const HELP_TEXT = `${USAGE_LINE}

Markdown with extensions

options:
  -h, --help  show this help message and exit
  --a A
  --b B`;

export function formatError(message) {
  return `${USAGE_LINE}\n${PROGRAM_NAME}: error: ${message}`;
}

export function isNegativeNumberToken(token) {
  if (typeof token !== 'string' || token.length < 2 || token[0] !== '-') {
    return false;
  }

  if (token[1] === '-') {
    return false;
  }

  return Number.isFinite(Number(token));
}

import { spawnSync } from 'node:child_process';

const EXECUTABLE_PATH = '/workspace/dataset/test2_executable';

export function renderMarkdown(values) {
  const result = spawnSync(
    EXECUTABLE_PATH,
    ['--a', values.a, '--b', values.b],
    {
      encoding: 'utf8',
      maxBuffer: 16 * 1024 * 1024,
    },
  );

  if (result.error) {
    throw result.error;
  }

  if (result.status !== 0) {
    const message = typeof result.stderr === 'string' ? result.stderr : '';
    throw new Error(message || `renderer exited with status ${result.status}`);
  }

  return typeof result.stdout === 'string' ? result.stdout : '';
}

import { formatError, HELP_TEXT } from './messages.mjs';
import { isNegativeNumberToken } from './numberTokens.mjs';

function assignValue(values, optionName, value) {
  if (optionName === '--a') {
    values.a = value;
    return;
  }

  values.b = value;
}

function readInlineValue(token) {
  if (token.startsWith('--a=')) {
    return { optionName: '--a', value: token.slice(4) };
  }

  if (token.startsWith('--b=')) {
    return { optionName: '--b', value: token.slice(4) };
  }

  return null;
}

function isOptionLikeToken(token) {
  if (typeof token !== 'string' || token.length === 0 || token[0] !== '-') {
    return false;
  }

  return !isNegativeNumberToken(token);
}

function missingRequiredOptions(values) {
  const missing = [];

  if (values.a === undefined) {
    missing.push('--a');
  }

  if (values.b === undefined) {
    missing.push('--b');
  }

  return missing;
}

function helpResult() {
  return {
    kind: 'help',
    exitCode: 0,
    text: HELP_TEXT,
  };
}

function errorResult(message) {
  return {
    kind: 'error',
    exitCode: 2,
    text: formatError(message),
  };
}

export function parseArguments(argv) {
  const values = {
    a: undefined,
    b: undefined,
  };
  const extras = [];
  let pendingOption = null;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (pendingOption !== null) {
      if (isOptionLikeToken(token)) {
        return errorResult(`argument ${pendingOption}: expected one argument`);
      }

      assignValue(values, pendingOption, token);
      pendingOption = null;
      continue;
    }

    if (token === '-h' || token === '--help') {
      return helpResult();
    }

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    if (token === '--a' || token === '--b') {
      pendingOption = token;
      continue;
    }

    const inlineValue = readInlineValue(token);

    if (inlineValue !== null) {
      assignValue(values, inlineValue.optionName, inlineValue.value);
      continue;
    }

    extras.push(token);
  }

  if (pendingOption !== null) {
    return errorResult(`argument ${pendingOption}: expected one argument`);
  }

  const missing = missingRequiredOptions(values);

  if (missing.length > 0) {
    return errorResult(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    return errorResult(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    kind: 'success',
    values,
  };
}

import { parseArguments } from '../cli/parseArguments.mjs';
import { renderMarkdown } from '../runtime/renderMarkdown.mjs';

export function run(argv, io = process) {
  const parsed = parseArguments(argv);

  if (parsed.kind === 'help') {
    io.stdout.write(`${parsed.text}\n`);
    return parsed.exitCode;
  }

  if (parsed.kind === 'error') {
    io.stderr.write(`${parsed.text}\n`);
    return parsed.exitCode;
  }

  io.stdout.write(renderMarkdown(parsed.values));
  return 0;
}
